<script lang="ts">
import{addElement,alignElements,distributeElements,groupElements,removeElements,reorderElement,ungroup,type Alignment}from'../commands.js';import type{EditorStore}from'../store.js';import{uuid,type LabelElement}from'../model.js';export let editor:EditorStore;let axis:'x'|'y'='x';let guideValue=10;
function create(type:'text'|'rectangle'|'ellipse'|'triangle'|'line'|'barcode'|'qr'){const base={id:uuid(),name:type[0].toUpperCase()+type.slice(1),transform:{x:5,y:5,width:type==='text'?25:12,height:type==='text'?7:12,rotation:0},zIndex:$editor.document.elements.length,visible:true,locked:false};let element:LabelElement;if(type==='text')element={...base,type,text:'Text',fontFamily:'sans-serif',fontSize:14,fontWeight:400,horizontalAlign:'left',verticalAlign:'top',overflow:'word-wrap'};else if(type==='barcode')element={...base,type,value:'123456789',symbology:'code128',showText:true};else if(type==='qr')element={...base,type,value:'https://makersbrain.com',errorCorrection:'M'};else element={...base,type,strokeWidth:.3,filled:false};editor.execute(addElement(element));editor.select([element.id])}
const align=(value:Alignment)=>editor.execute(alignElements($editor.selection,value));const reorder=(value:'front'|'back'|'forward'|'backward')=>{const id=[...$editor.selection][0];if(id)editor.execute(reorderElement(id,value))};function addGuide(){if(Number.isFinite(guideValue))editor.setView({manualGuides:[...$editor.view.manualGuides,{axis,value:guideValue}]})}function editGuide(index:number,value:number){const guides=$editor.view.manualGuides.map((guide,i)=>i===index?{...guide,value}:guide);editor.setView({manualGuides:guides})}function removeGuide(index:number){editor.setView({manualGuides:$editor.view.manualGuides.filter((_,i)=>i!==index)})}function del(){editor.execute(removeElements($editor.selection));editor.clearSelection()}function group(){editor.execute(groupElements($editor.selection))}function ungroupSelected(){for(const id of $editor.selection)editor.execute(ungroup(id));editor.clearSelection()}
</script>
<nav aria-label="Editor tools">{#each ['text','rectangle','ellipse','triangle','line','barcode','qr'] as type}<button on:click={()=>create(type as Parameters<typeof create>[0])}>{type[0].toUpperCase()+type.slice(1)}</button>{/each}<span></span>{#each ['left','center-x','right','top','center-y','bottom'] as item}<button on:click={()=>align(item as Alignment)} disabled={$editor.selection.size<2}>{item}</button>{/each}<button on:click={()=>editor.execute(distributeElements($editor.selection,'horizontal'))} disabled={$editor.selection.size<3}>Distribute X</button><button on:click={()=>editor.execute(distributeElements($editor.selection,'vertical'))} disabled={$editor.selection.size<3}>Distribute Y</button>{#each ['front','forward','backward','back'] as item}<button on:click={()=>reorder(item as Parameters<typeof reorder>[0])} disabled={$editor.selection.size!==1}>{item}</button>{/each}<label>Guide<select bind:value={axis}><option value="x">X</option><option value="y">Y</option></select><input type="number" step=".1" bind:value={guideValue}></label><button on:click={addGuide}>Add guide</button>{#each $editor.view.manualGuides as guide,index}<label>{guide.axis.toUpperCase()} guide<input aria-label={`${guide.axis.toUpperCase()} guide ${index+1}`} type="number" step=".1" value={guide.value} on:change={e=>editGuide(index,+e.currentTarget.value)}></label><button aria-label={`Remove guide ${index+1}`} on:click={()=>removeGuide(index)}>×</button>{/each}<label class="check"><input type="checkbox" checked={$editor.view.showGrid} on:change={e=>editor.setView({showGrid:e.currentTarget.checked})}>Grid</label><label>Grid mm<input type="number" min=".1" step=".1" value={$editor.view.gridSize} on:change={e=>editor.setView({gridSize:Math.max(.1,+e.currentTarget.value)})}></label><label class="check"><input type="checkbox" checked={$editor.view.showRulers} on:change={e=>editor.setView({showRulers:e.currentTarget.checked})}>Rulers</label><label class="check"><input type="checkbox" checked={$editor.view.snapping} on:change={e=>editor.setView({snapping:e.currentTarget.checked})}>Snap</label><button on:click={()=>editor.undo()} disabled={!$editor.canUndo}>Undo</button><button on:click={()=>editor.redo()} disabled={!$editor.canRedo}>Redo</button><button on:click={group} disabled={$editor.selection.size<2}>Group</button><button on:click={ungroupSelected} disabled={!$editor.selectedElements.some(e=>e.type==='group')}>Ungroup</button><button on:click={del} disabled={!$editor.selection.size}>Delete</button><label>Zoom<input class="zoom" type="range" min=".25" max="4" step=".25" value={$editor.view.zoom} on:input={(e)=>editor.setView({zoom:+e.currentTarget.value})}></label></nav>
<style>nav{display:flex;gap:.35rem;align-items:center;overflow:auto;padding:.6rem;background:#f7f4ed;border-bottom:1px solid #d8d0c3}nav span{flex:1}button,label{white-space:nowrap}label{display:flex;gap:.2rem}.zoom{width:5rem}</style>
